73	const log = {
74	  info(message: string, meta?: LogMeta) {
75	    console.log(formatLog('info', message, meta));
76	  },
77	  success(message: string, meta?: LogMeta) {
78	    console.log(formatLog('success', message, meta));
79	  },
80	  warn(message: string, meta?: LogMeta) {
81	    console.warn(formatLog('warn', message, meta));
82	  },
83	  error(message: string, meta?: LogMeta) {
84	    console.error(formatLog('error', message, meta));
85	  }
