function parseThresholds(thresholdArgs: string | string[] | undefined): {
  thresholds: Record<string, number> | null;
  error: string | null;
} {
  if (!thresholdArgs) {
    return { thresholds: null, error: null };
  }

  const args = Array.isArray(thresholdArgs) ? thresholdArgs : [thresholdArgs];
  const thresholds: Record<string, number> = {};
  const validMetricIds = ['exact_match', 'toxicity', 'length_variance'];

  for (const arg of args) {
    const match = arg.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      return {
        thresholds: null,
        error: `Malformed threshold: ${arg} (expected format: metric=min_score)`
      };
    }

    const [, metricId, scoreStr] = match;
    const score = Number.parseFloat(scoreStr);

    if (Number.isNaN(score) || score < 0 || score > 1) {
      return {
        thresholds: null,
        error: `Invalid threshold value: ${scoreStr} (must be between 0 and 1)`
      };
    }

    if (!validMetricIds.includes(metricId)) {
      return {
        thresholds: null,
        error: `Unknown metric: ${metricId} (valid metrics: ${validMetricIds.join(', ')})`
      };
    }

    thresholds[metricId] = score;
  }

  return { thresholds, error: null };
}

function runEvalCommand(options: EvalOptions) {
  const { thresholds, error: thresholdError } = parseThresholds(options.threshold);

  if (thresholdError) {
    log.error(`Threshold error: ${thresholdError}`);
    process.exit(2);
  }

  assertFileExists(options.outputs);
  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });
  const report = (Eval.generateReport as unknown as (config: unknown) => any)({
    evaluations,
    outputsPath: dataset.outputsPath,
    referencesPath: dataset.referencesPath,
    thresholds
  });
  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (thresholds && report.passed === false) {
    process.exit(1);
  }
}

